function detectName(from, subject) {
  const text = `${from || ''} ${subject || ''}`;
  if (text.includes('nugget')) return '너겟레터';
  if (text.includes('soonsal')) return '순살브리핑';
  if (text.includes('newneek')) return '뉴닉';
  if (text.includes('daily-byte')) return '데일리바이트';
  if (text.includes('uppity')) return '어피티';
  if (text.includes('mk.co.kr') || text.includes('dig')) return '디그';
  return '미분류';
}
return items.map(item => {
  const headers = item.json.headers || {};
  const sender = item.json.from || headers.from || '';
  const subject = item.json.subject || headers.subject || '';
  return { json: {
    newsletter_name: detectName(sender, subject),
    sender,
    subject,
    body: item.json.textPlain || item.json.textHtml || item.json.snippet || '',
    received_date: (item.json.date || new Date().toISOString()).slice(0, 10),
    message_id: item.json.id || headers['message-id']
  } };
});
